'use client';

import { useState } from 'react';

import { AuthFrame, StepSwap } from './auth-kit';
import { ResetFlow } from './reset-flow';
import { SignInFlow } from './sign-in-flow';
import { SignUpFlow } from './sign-up-flow';

type Flow = 'sign-in' | 'sign-up' | 'reset';

const FOOTERS: Record<Flow, string> = {
  'sign-in':
    'Trouble signing in? A workspace admin can send you a new invitation.',
  'sign-up':
    'By creating an account you accept the terms of service and the privacy notice',
  reset:
    'For your safety, this page never says whether an account uses an address',
};

export default function Application04() {
  const [flow, setFlow] = useState<Flow>('sign-in');
  const [hasMoved, setHasMoved] = useState(false);

  function open(nextFlow: Flow) {
    setFlow(nextFlow);
    setHasMoved(true);
  }

  function openSignIn() {
    open('sign-in');
  }

  function openSignUp() {
    open('sign-up');
  }

  function openReset() {
    open('reset');
  }

  return (
    <AuthFrame footer={FOOTERS[flow]}>
      <StepSwap stepKey={flow}>
        {flow === 'sign-in' && (
          <SignInFlow
            startsFocused={hasMoved}
            onCreateAccount={openSignUp}
            onForgotPassword={openReset}
          />
        )}
        {flow === 'sign-up' && (
          <SignUpFlow startsFocused={hasMoved} onSignIn={openSignIn} />
        )}
        {flow === 'reset' && (
          <ResetFlow startsFocused={hasMoved} onSignIn={openSignIn} />
        )}
      </StepSwap>
    </AuthFrame>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { LoaderCircleIcon, type Icon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { FieldError } from '@/registry/ndeko/ui/field';

import { LoomboardMark } from './brand-mark';
import { PRODUCT_NAME } from './data';

const STEP_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const STEP_OUT: Transition = { duration: 0.15, ease: [0.23, 1, 0.32, 1] };

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const STEP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.98, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)', transition: STEP_IN },
  exit: { opacity: 0, scale: 0.98, filter: 'blur(2px)', transition: STEP_OUT },
};

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const ERROR_VARIANTS: Variants = {
  enter: { height: 0, opacity: 0 },
  visible: { height: 'auto', opacity: 1, transition: STEP_IN },
  exit: { height: 0, opacity: 0, transition: STEP_OUT },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1, transition: STEP_IN },
  exit: { opacity: 0, transition: STEP_OUT },
};

function stepVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return STEP_VARIANTS;
}

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function errorVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ERROR_VARIANTS;
}

type AuthFrameProps = {
  footer?: React.ReactNode;
  children: React.ReactNode;
};

/** A focused page: the window colour, the mark and its name, one card in the middle. */
export function AuthFrame({ footer, children }: AuthFrameProps) {
  return (
    <div className='bg-sidebar text-foreground flex min-h-dvh w-full flex-col'>
      <header className='flex h-14 shrink-0 items-center gap-2 px-4 sm:px-6'>
        <LoomboardMark />
        <span className='text-sm font-semibold'>{PRODUCT_NAME}</span>
      </header>
      <main className='flex flex-1 flex-col items-center px-4 pt-4 pb-16 sm:justify-center sm:pt-0'>
        <div className='flex w-full max-w-[25rem] flex-col gap-4'>
          <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl p-6 shadow-[0_1px_2px_rgb(0_0_0/0.04)] sm:p-7'>
            <AnimatedSize contentClassName='relative'>{children}</AnimatedSize>
          </div>
          {footer && (
            <p className='text-muted-foreground px-2 text-center text-xs text-balance'>
              {footer}
            </p>
          )}
        </div>
      </main>
    </div>
  );
}

type StepSwapProps = {
  stepKey: string;
  children: React.ReactNode;
};

/** The card resizes around it while one step gives way to the next. */
export function StepSwap({ stepKey, children }: StepSwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = stepVariantsOf(shouldReduceMotion);

  return (
    <AnimatePresence mode='popLayout' initial={false}>
      <motion.div
        key={stepKey}
        variants={variants}
        initial='enter'
        animate='visible'
        exit='exit'
        className='flex flex-col gap-6'
      >
        {children}
      </motion.div>
    </AnimatePresence>
  );
}

type MarkTileProps = { icon: Icon };

export function MarkTile({ icon: TileIcon }: MarkTileProps) {
  return (
    <span className='keycap-3d text-muted-foreground flex size-10 items-center justify-center rounded-lg'>
      <TileIcon className='size-5' />
    </span>
  );
}

type CardHeadProps = {
  mark: React.ReactNode;
  title: string;
  /** Focuses the title when a step opens, so screen readers hear where they are. */
  autoFocusTitle?: boolean;
  children: React.ReactNode;
};

export function CardHead({
  mark,
  title,
  autoFocusTitle,
  children,
}: CardHeadProps) {
  const titleRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    if (autoFocusTitle) {
      titleRef.current?.focus();
    }
  }, [autoFocusTitle]);

  return (
    <div className='flex flex-col gap-4'>
      {mark}
      <div className='flex flex-col gap-1.5'>
        <h1
          ref={titleRef}
          tabIndex={-1}
          className='text-xl font-semibold text-balance outline-none'
        >
          {title}
        </h1>
        <p className='text-muted-foreground text-[13px] text-pretty'>
          {children}
        </p>
      </div>
    </div>
  );
}

type ErrorPresenceProps = {
  error: string | null;
};

/** Rendered inside a `Field`, so the error is tied to its control. It grows in and folds away. */
export function ErrorPresence({ error }: ErrorPresenceProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = errorVariantsOf(shouldReduceMotion);

  return (
    <AnimatePresence initial={false}>
      {error && (
        <motion.div
          key='error'
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          className='overflow-hidden'
        >
          <FieldError match className='pt-1.5'>
            {error}
          </FieldError>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

type SubmitButtonProps = {
  label: string;
  workingLabel: string;
  isWorking: boolean;
};

/** Becomes its working state in place: a spinner joins the label and the pill resizes to it. */
export function SubmitButton({
  label,
  workingLabel,
  isWorking,
}: SubmitButtonProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const shownLabel = workingLabelOf(isWorking, label, workingLabel);

  return (
    <Button
      type='submit'
      size='lg'
      disabled={isWorking}
      focusableWhenDisabled
      className='w-full data-disabled:opacity-100 sm:w-auto'
    >
      <AnimatedSize
        as='span'
        axis='width'
        contentClassName='relative flex items-center gap-2'
      >
        <AnimatePresence mode='popLayout' initial={false}>
          {isWorking && (
            <motion.span
              key='spinner'
              variants={variants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
              className='flex'
            >
              <LoaderCircleIcon className='animate-spin' />
            </motion.span>
          )}
        </AnimatePresence>
        <AnimatePresence mode='popLayout' initial={false}>
          <motion.span
            key={shownLabel}
            variants={variants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={SWAP_TRANSITION}
          >
            {shownLabel}
          </motion.span>
        </AnimatePresence>
      </AnimatedSize>
    </Button>
  );
}

function workingLabelOf(
  isWorking: boolean,
  label: string,
  workingLabel: string
) {
  if (isWorking) {
    return workingLabel;
  }
  return label;
}

type SwapLabelProps = { text: string };

export function SwapLabel({ text }: SwapLabelProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);

  return (
    <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={text}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
          className='tabular-nums'
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </AnimatedSize>
  );
}

/** Counts down once a second while it is above zero. */
export function useCountdown() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    if (seconds <= 0) {
      return;
    }
    const timer = window.setTimeout(() => {
      setSeconds((current) => current - 1);
    }, 1000);
    return () => window.clearTimeout(timer);
  }, [seconds]);

  return { seconds, start: setSeconds };
}

export function clockOf(totalSeconds: number) {
  const rawMinutes = totalSeconds / 60;
  const minutes = Math.floor(rawMinutes);
  const seconds = totalSeconds % 60;
  const paddedSeconds = String(seconds).padStart(2, '0');
  return `${minutes}:${paddedSeconds}`;
}

'use client';

import { Fragment, useEffect, useRef, useState } from 'react';

import { MailIcon, ShieldCheckIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Field, FieldLabel } from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';
import {
  OTPField,
  OTPFieldInput,
  OTPFieldSeparator,
} from '@/registry/ndeko/ui/otp-field';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';

import {
  CardHead,
  ErrorPresence,
  MarkTile,
  StepSwap,
  SubmitButton,
  SwapLabel,
  clockOf,
  useCountdown,
} from './auth-kit';
import {
  CHECK_DELAY_MS,
  CODE_LENGTH,
  CODE_LIFETIME_MINUTES,
  EMAIL_PLACEHOLDER,
  PREVIEW_CODE,
  PREVIEW_CODE_LABEL,
  RESEND_SECONDS,
  RESENT_NOTICE_MS,
  PRODUCT_NAME,
  SEND_DELAY_MS,
} from './data';
import { emailProblemOf } from './email-check';

type Step = 'email' | 'code' | 'done';

const SLOTS = Array.from({ length: CODE_LENGTH }, (_, index) => index);

const SEPARATOR_AFTER = 2;

function slotLabelOf(index: number) {
  const position = index + 1;
  return `Digit ${position} of ${CODE_LENGTH}`;
}

function resendLabelOf(seconds: number, isResent: boolean) {
  if (isResent) {
    return 'New code sent';
  }
  if (seconds > 0) {
    const clock = clockOf(seconds);
    return `Send a new code in ${clock}`;
  }
  return 'Send a new code';
}

type SignInFlowProps = {
  startsFocused: boolean;
  onCreateAccount: () => void;
  onForgotPassword: () => void;
};

export function SignInFlow({
  startsFocused,
  onCreateAccount,
  onForgotPassword,
}: SignInFlowProps) {
  const [step, setStep] = useState<Step>('email');
  const [hasMoved, setHasMoved] = useState(startsFocused);
  const [email, setEmail] = useState('');
  const [emailError, setEmailError] = useState<string | null>(null);
  const [isSending, setIsSending] = useState(false);
  const [code, setCode] = useState('');
  const [codeError, setCodeError] = useState<string | null>(null);
  const [checkingCode, setCheckingCode] = useState<string | null>(null);
  const [isResent, setIsResent] = useState(false);
  const { seconds: resendSeconds, start: startCountdown } = useCountdown();
  const emailRef = useRef<HTMLInputElement>(null);
  const trimmedEmail = email.trim();
  const hasEmailError = Boolean(emailError);
  const hasCodeError = Boolean(codeError);
  const isChecking = checkingCode !== null;
  const isResendWaiting = resendSeconds > 0;
  const resendLabel = resendLabelOf(resendSeconds, isResent);

  useEffect(() => {
    if (!isSending) {
      return;
    }
    const timer = window.setTimeout(() => {
      setIsSending(false);
      setCode('');
      setCodeError(null);
      setStep('code');
      setHasMoved(true);
      startCountdown(RESEND_SECONDS);
    }, SEND_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [isSending, startCountdown]);

  useEffect(() => {
    if (checkingCode === null) {
      return;
    }
    const timer = window.setTimeout(() => {
      const isRight = checkingCode === PREVIEW_CODE;
      setCheckingCode(null);
      if (isRight) {
        setStep('done');
        return;
      }
      setCodeError(
        'That code does not match. Check the latest email or send a new one'
      );
    }, CHECK_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [checkingCode]);

  useEffect(() => {
    if (!isResent) {
      return;
    }
    const timer = window.setTimeout(() => setIsResent(false), RESENT_NOTICE_MS);
    return () => window.clearTimeout(timer);
  }, [isResent]);

  function changeEmail(event: React.ChangeEvent<HTMLInputElement>) {
    setEmail(event.target.value);
    setEmailError(null);
  }

  function submitEmail(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (isSending) {
      return;
    }
    const problem = emailProblemOf(email, 'Enter your work email');
    setEmailError(problem);
    if (problem) {
      emailRef.current?.focus();
      return;
    }
    setIsSending(true);
  }

  function changeCode(value: string) {
    setCode(value);
    setCodeError(null);
  }

  function completeCode(value: string) {
    setCheckingCode(value);
  }

  function submitCode(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (isChecking) {
      return;
    }
    const isComplete = code.length === CODE_LENGTH;
    if (!isComplete) {
      setCodeError(`Enter the ${CODE_LENGTH} digits from the email`);
      return;
    }
    setCheckingCode(code);
  }

  function resendCode() {
    setCode('');
    setCodeError(null);
    setIsResent(true);
    startCountdown(RESEND_SECONDS);
  }

  function switchEmail() {
    setStep('email');
    setHasMoved(true);
  }

  function signOut() {
    setCode('');
    setStep('email');
    setHasMoved(true);
  }

  return (
    <StepSwap stepKey={step}>
      {step === 'email' && (
        <>
          <CardHead
            mark={<MarkTile icon={MailIcon} />}
            title={`Sign in to ${PRODUCT_NAME}`}
          >
            We email you a 6-digit code to sign in on this device.
          </CardHead>
          <form
            noValidate
            onSubmit={submitEmail}
            className='flex flex-col gap-5'
          >
            <Field invalid={hasEmailError} className='gap-0'>
              <FieldLabel className='mb-1.5'>Work email</FieldLabel>
              <Input
                ref={emailRef}
                type='email'
                inputMode='email'
                autoComplete='email'
                placeholder={EMAIL_PLACEHOLDER}
                value={email}
                readOnly={isSending}
                autoFocus={hasMoved}
                onChange={changeEmail}
              />
              <ErrorPresence error={emailError} />
            </Field>
            <div className='flex flex-col-reverse gap-3 sm:flex-row sm:items-center sm:justify-between'>
              <p className='text-muted-foreground text-xs'>
                {`Codes expire after ${CODE_LIFETIME_MINUTES} minutes`}
              </p>
              <SubmitButton
                label='Send code'
                workingLabel='Sending code'
                isWorking={isSending}
              />
            </div>
          </form>
          <div className='text-muted-foreground flex flex-wrap items-center justify-between gap-x-4 gap-y-1 text-xs'>
            <p>
              {`New to ${PRODUCT_NAME}? `}
              <Button
                variant='link'
                onClick={onCreateAccount}
                className='h-auto px-0 text-xs'
              >
                Create an account
              </Button>
            </p>
            <Button
              variant='link'
              onClick={onForgotPassword}
              className='h-auto px-0 text-xs'
            >
              Forgot your password
            </Button>
          </div>
        </>
      )}
      {step === 'code' && (
        <>
          <CardHead
            mark={<MarkTile icon={ShieldCheckIcon} />}
            title='Check your email'
          >
            Enter the code sent to{' '}
            <span className='text-foreground font-medium break-all'>
              {trimmedEmail}
            </span>
            .{' '}
            <Button
              variant='link'
              onClick={switchEmail}
              className='h-auto px-0 text-[13px]'
            >
              Use another email
            </Button>
          </CardHead>
          <form
            noValidate
            onSubmit={submitCode}
            className='flex flex-col gap-5'
          >
            <Field invalid={hasCodeError} className='gap-0'>
              <FieldLabel className='mb-1.5'>
                {`${CODE_LENGTH}-digit code`}
              </FieldLabel>
              <OTPField
                length={CODE_LENGTH}
                value={code}
                autoComplete='one-time-code'
                readOnly={isChecking}
                onValueChange={changeCode}
                onValueComplete={completeCode}
                className='gap-1.5 sm:gap-2'
              >
                {SLOTS.map((index) => {
                  const isFirst = index === 0;
                  const isSeparated = index === SEPARATOR_AFTER;

                  return (
                    <Fragment key={index}>
                      <OTPFieldInput
                        autoFocus={isFirst}
                        aria-label={slotLabelOf(index)}
                        className='sm:size-11'
                      />
                      {isSeparated && <OTPFieldSeparator />}
                    </Fragment>
                  );
                })}
              </OTPField>
              <ErrorPresence error={codeError} />
            </Field>
            <p className='bg-foreground/[0.03] text-muted-foreground rounded-lg px-3 py-2 text-xs'>
              This preview sends no email. The code it accepts is{' '}
              <span className='text-foreground font-medium tabular-nums'>
                {PREVIEW_CODE_LABEL}
              </span>
            </p>
            <div className='flex flex-col-reverse gap-3 sm:flex-row sm:items-center sm:justify-between'>
              <Button
                type='button'
                variant='ghost'
                size='sm'
                disabled={isResendWaiting}
                onClick={resendCode}
                className='text-muted-foreground self-center sm:self-auto'
              >
                <SwapLabel text={resendLabel} />
              </Button>
              <SubmitButton
                label='Sign in'
                workingLabel='Checking'
                isWorking={isChecking}
              />
            </div>
          </form>
        </>
      )}
      {step === 'done' && (
        <>
          <CardHead
            mark={<StatusOrb tone='success' />}
            title='Signed in'
            autoFocusTitle
          >
            <span className='text-foreground font-medium break-all'>
              {trimmedEmail}
            </span>{' '}
            {`is signed in to ${PRODUCT_NAME} on this device.`}
          </CardHead>
          <div className='flex flex-col-reverse gap-3 sm:flex-row sm:items-center sm:justify-between'>
            <p className='text-muted-foreground text-xs'>
              Sessions on this device last 30 days
            </p>
            <Button variant='outline' size='lg' onClick={signOut}>
              Sign out
            </Button>
          </div>
        </>
      )}
    </StepSwap>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { MailIcon, UserRoundPlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Field, FieldLabel } from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';

import {
  CardHead,
  ErrorPresence,
  MarkTile,
  StepSwap,
  SubmitButton,
} from './auth-kit';
import {
  CREATE_DELAY_MS,
  EMAIL_PLACEHOLDER,
  LINK_LIFETIME_HOURS,
  PRODUCT_NAME,
} from './data';
import { emailProblemOf } from './email-check';
import {
  PasswordField,
  PasswordRules,
  areRulesMet,
  personalWordsOf,
  rulesOf,
} from './password-parts';

type Step = 'form' | 'confirm';

type SignUpField = 'name' | 'email' | 'password';

type SignUpErrors = Partial<Record<SignUpField, string>>;

const FIELD_ORDER: SignUpField[] = ['name', 'email', 'password'];

function signUpEmailProblemOf(email: string) {
  const problem = emailProblemOf(email, 'Enter your work email');
  return problem ?? undefined;
}

function nameProblemOf(name: string) {
  const trimmed = name.trim();
  if (trimmed.length === 0) {
    return 'Enter your name as teammates will see it';
  }
  return undefined;
}

function passwordProblemOf(isPasswordReady: boolean) {
  if (isPasswordReady) {
    return undefined;
  }
  return 'Meet every rule below to continue';
}

function firstErrorFieldOf(errors: SignUpErrors) {
  const field = FIELD_ORDER.find((candidate) => Boolean(errors[candidate]));
  if (field) {
    return field;
  }
  return null;
}

function withoutError(errors: SignUpErrors, field: SignUpField) {
  if (!errors[field]) {
    return errors;
  }
  const next = { ...errors };
  delete next[field];
  return next;
}

function errorOf(errors: SignUpErrors, field: SignUpField) {
  return errors[field] ?? null;
}

type SignUpFlowProps = {
  startsFocused: boolean;
  onSignIn: () => void;
};

export function SignUpFlow({ startsFocused, onSignIn }: SignUpFlowProps) {
  const [step, setStep] = useState<Step>('form');
  const [hasMoved, setHasMoved] = useState(startsFocused);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errors, setErrors] = useState<SignUpErrors>({});
  const [isCreating, setIsCreating] = useState(false);
  const nameRef = useRef<HTMLInputElement>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);
  const personalWords = personalWordsOf(name, email);
  const rules = rulesOf(password, personalWords);
  const isPasswordReady = areRulesMet(rules);
  const trimmedEmail = email.trim();
  const nameError = errorOf(errors, 'name');
  const emailError = errorOf(errors, 'email');
  const passwordError = errorOf(errors, 'password');
  const hasNameError = Boolean(nameError);
  const hasEmailError = Boolean(emailError);

  useEffect(() => {
    if (!isCreating) {
      return;
    }
    const timer = window.setTimeout(() => {
      setIsCreating(false);
      setPassword('');
      setStep('confirm');
      setHasMoved(true);
    }, CREATE_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [isCreating]);

  function clearError(field: SignUpField) {
    setErrors((previous) => withoutError(previous, field));
  }

  function changeName(event: React.ChangeEvent<HTMLInputElement>) {
    setName(event.target.value);
    clearError('name');
  }

  function changeEmail(event: React.ChangeEvent<HTMLInputElement>) {
    setEmail(event.target.value);
    clearError('email');
  }

  function changePassword(value: string) {
    setPassword(value);
    clearError('password');
  }

  function focusField(field: SignUpField) {
    const refs = { name: nameRef, email: emailRef, password: passwordRef };
    refs[field].current?.focus();
  }

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (isCreating) {
      return;
    }
    const nextErrors: SignUpErrors = {
      name: nameProblemOf(name),
      email: signUpEmailProblemOf(email),
      password: passwordProblemOf(isPasswordReady),
    };
    const firstField = firstErrorFieldOf(nextErrors);
    setErrors(nextErrors);
    if (firstField) {
      focusField(firstField);
      return;
    }
    setIsCreating(true);
  }

  function switchEmail() {
    setStep('form');
    setHasMoved(true);
  }

  return (
    <StepSwap stepKey={step}>
      {step === 'form' && (
        <>
          <CardHead
            mark={<MarkTile icon={UserRoundPlusIcon} />}
            title={`Create your ${PRODUCT_NAME} account`}
          >
            Start a workspace for your team. You can invite people once it is
            ready.
          </CardHead>
          <form noValidate onSubmit={submit} className='flex flex-col gap-5'>
            <Field invalid={hasNameError} className='gap-0'>
              <FieldLabel className='mb-1.5'>Full name</FieldLabel>
              <Input
                ref={nameRef}
                autoComplete='name'
                placeholder='Amara Okafor'
                value={name}
                readOnly={isCreating}
                autoFocus={hasMoved}
                onChange={changeName}
              />
              <ErrorPresence error={nameError} />
            </Field>
            <Field invalid={hasEmailError} className='gap-0'>
              <FieldLabel className='mb-1.5'>Work email</FieldLabel>
              <Input
                ref={emailRef}
                type='email'
                inputMode='email'
                autoComplete='email'
                placeholder={EMAIL_PLACEHOLDER}
                value={email}
                readOnly={isCreating}
                onChange={changeEmail}
              />
              <ErrorPresence error={emailError} />
            </Field>
            <PasswordField
              label='Password'
              value={password}
              autoComplete='new-password'
              error={passwordError}
              inputRef={passwordRef}
              readOnly={isCreating}
              onValueChange={changePassword}
            >
              <PasswordRules rules={rules} />
            </PasswordField>
            <SubmitButton
              label='Create account'
              workingLabel='Creating account'
              isWorking={isCreating}
            />
          </form>
          <p className='text-muted-foreground text-xs'>
            {'Already have an account? '}
            <Button
              variant='link'
              onClick={onSignIn}
              className='h-auto px-0 text-xs'
            >
              Sign in
            </Button>
          </p>
        </>
      )}
      {step === 'confirm' && (
        <>
          <CardHead
            mark={<MarkTile icon={MailIcon} />}
            title='Confirm your email'
            autoFocusTitle
          >
            We sent a link to{' '}
            <span className='text-foreground font-medium break-all'>
              {trimmedEmail}
            </span>
            {`. Open it within ${LINK_LIFETIME_HOURS} hours to finish creating your account.`}
          </CardHead>
          <p className='bg-foreground/[0.03] text-muted-foreground rounded-lg px-3 py-2 text-xs'>
            This preview sends no email and keeps no password
          </p>
          <div className='flex flex-col-reverse gap-3 sm:flex-row sm:items-center sm:justify-between'>
            <Button
              variant='link'
              onClick={onSignIn}
              className='h-auto self-center px-0 text-xs sm:self-auto'
            >
              Back to sign in
            </Button>
            <Button variant='outline' size='lg' onClick={switchEmail}>
              Use another email
            </Button>
          </div>
        </>
      )}
    </StepSwap>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { LockIcon, MailIcon } from '@/registry/ndeko/lib/icons';
