  CHANGE_DELAY_MS,
  EMAIL_PLACEHOLDER,
  LINK_LIFETIME_MINUTES,
  RESEND_SECONDS,
  RESENT_NOTICE_MS,
  SEND_DELAY_MS,
} from './data';
