type Step = 'request' | 'sent' | 'choose' | 'done';

function resendLabelOf(seconds: number, isResent: boolean) {
  if (isResent) {
    return 'Link sent again';
  }
  if (seconds > 0) {
    const clock = clockOf(seconds);
    return `Send it again in ${clock}`;
  }
  return 'Send it again';
}

function matchRuleOf(password: string, confirmation: string): PasswordRule {
  const hasConfirmation = confirmation.length > 0;
  const isSame = password === confirmation;
  const isMatch = hasConfirmation && isSame;
  return { id: 'match', label: 'Both fields match', isMet: isMatch };
}

type ResetFlowProps = {
  startsFocused: boolean;
  onSignIn: () => void;
};

export function ResetFlow({ startsFocused, onSignIn }: ResetFlowProps) {
  const [step, setStep] = useState<Step>('request');
  const [hasMoved, setHasMoved] = useState(startsFocused);
  const [email, setEmail] = useState('');
  const [emailError, setEmailError] = useState<string | null>(null);
  const [isSending, setIsSending] = useState(false);
  const [isResent, setIsResent] = useState(false);
  const [password, setPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [passwordError, setPasswordError] = useState<string | null>(null);
  const [confirmationError, setConfirmationError] = useState<string | null>(
    null
  );
  const [isChanging, setIsChanging] = useState(false);
  const { seconds: resendSeconds, start: startCountdown } = useCountdown();
  const emailRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);
  const confirmationRef = useRef<HTMLInputElement>(null);
  const trimmedEmail = email.trim();
  const hasEmailError = Boolean(emailError);
  const isResendWaiting = resendSeconds > 0;
  const resendLabel = resendLabelOf(resendSeconds, isResent);
  const personalWords = personalWordsOf('', email);
  const passwordRules = rulesOf(password, personalWords);
  const matchRule = matchRuleOf(password, confirmation);
  const rules = [...passwordRules, matchRule];
  const isPasswordReady = areRulesMet(passwordRules);

  useEffect(() => {
    if (!isSending) {
      return;
    }
    const timer = window.setTimeout(() => {
      setIsSending(false);
      setStep('sent');
      setHasMoved(true);
      startCountdown(RESEND_SECONDS);
    }, SEND_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [isSending, startCountdown]);

  useEffect(() => {
    if (!isChanging) {
      return;
    }
    const timer = window.setTimeout(() => {
      setIsChanging(false);
      setPassword('');
      setConfirmation('');
      setStep('done');
    }, CHANGE_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [isChanging]);

  useEffect(() => {
    if (!isResent) {
      return;
    }
    const timer = window.setTimeout(() => setIsResent(false), RESENT_NOTICE_MS);
    return () => window.clearTimeout(timer);
  }, [isResent]);

  function changeEmail(event: React.ChangeEvent<HTMLInputElement>) {
    setEmail(event.target.value);
    setEmailError(null);
  }

  function requestLink(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (isSending) {
      return;
    }
    const problem = emailProblemOf(email, 'Enter the email you sign in with');
    setEmailError(problem);
    if (problem) {
      emailRef.current?.focus();
      return;
    }
    setIsSending(true);
  }

  function resendLink() {
    setIsResent(true);
    startCountdown(RESEND_SECONDS);
  }

  function switchEmail() {
    setStep('request');
    setHasMoved(true);
  }

  function openLink() {
    setPasswordError(null);
    setConfirmationError(null);
    setStep('choose');
    setHasMoved(true);
  }

  function changePassword(value: string) {
    setPassword(value);
    setPasswordError(null);
  }

  function changeConfirmation(value: string) {
    setConfirmation(value);
    setConfirmationError(null);
  }

  function changePasswordNow(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (isChanging) {
      return;
    }
    if (!isPasswordReady) {
      setPasswordError('Meet every rule below to continue');
      passwordRef.current?.focus();
      return;
    }
    if (!matchRule.isMet) {
      setConfirmationError('Type the same password in both fields');
      confirmationRef.current?.focus();
      return;
    }
    setIsChanging(true);
  }

  return (
    <StepSwap stepKey={step}>
      {step === 'request' && (
        <>
          <CardHead
            mark={<MarkTile icon={LockIcon} />}
            title='Reset your password'
          >
            Enter the email you sign in with and we send a link to choose a new
            password.
          </CardHead>
          <form
            noValidate
            onSubmit={requestLink}
            className='flex flex-col gap-5'
          >
            <Field invalid={hasEmailError} className='gap-0'>
              <FieldLabel className='mb-1.5'>Email</FieldLabel>
              <Input
                ref={emailRef}
                type='email'
                inputMode='email'
                autoComplete='email'
                placeholder={EMAIL_PLACEHOLDER}
                value={email}
                readOnly={isSending}
                autoFocus={hasMoved}
                onChange={changeEmail}
              />
              <ErrorPresence error={emailError} />
            </Field>
            <div className='flex flex-col-reverse gap-3 sm:flex-row sm:items-center sm:justify-between'>
              <p className='text-muted-foreground text-xs'>
                {`The link works for ${LINK_LIFETIME_MINUTES} minutes`}
              </p>
              <SubmitButton
                label='Send reset link'
                workingLabel='Sending link'
                isWorking={isSending}
              />
            </div>
          </form>
          <Button
            variant='link'
            onClick={onSignIn}
            className='h-auto self-start px-0 text-xs'
          >
            Back to sign in
          </Button>
        </>
      )}
      {step === 'sent' && (
        <>
          <CardHead
            mark={<MarkTile icon={MailIcon} />}
            title='Check your email'
            autoFocusTitle
          >
            If an account uses{' '}
            <span className='text-foreground font-medium break-all'>
              {trimmedEmail}
            </span>
            {`, a reset link is on its way. It works for ${LINK_LIFETIME_MINUTES} minutes.`}
          </CardHead>
          <p className='bg-foreground/[0.03] text-muted-foreground rounded-lg px-3 py-2 text-xs'>
            This preview sends no email. Open the link from here instead.
          </p>
          <div className='flex flex-col gap-3'>
            <div className='flex flex-col-reverse gap-3 sm:flex-row sm:items-center sm:justify-between'>
              <Button
                variant='ghost'
                size='sm'
                disabled={isResendWaiting}
                onClick={resendLink}
                className='text-muted-foreground self-center sm:self-auto'
              >
                <SwapLabel text={resendLabel} />
              </Button>
              <Button size='lg' onClick={openLink} className='w-full sm:w-auto'>
                Open the reset link
              </Button>
            </div>
            <Button
              variant='link'
              onClick={switchEmail}
              className='h-auto self-center px-0 text-xs sm:self-start'
            >
              Use another email
            </Button>
          </div>
        </>
      )}
      {step === 'choose' && (
        <>
          <CardHead
            mark={<MarkTile icon={LockIcon} />}
            title='Choose a new password'
          >
            For{' '}
            <span className='text-foreground font-medium break-all'>
              {trimmedEmail}
            </span>
            . Other devices sign out once it changes.
          </CardHead>
          <form
            noValidate
            onSubmit={changePasswordNow}
            className='flex flex-col gap-5'
          >
            <PasswordField
              label='New password'
              value={password}
              autoComplete='new-password'
              error={passwordError}
              inputRef={passwordRef}
              autoFocus
              readOnly={isChanging}
              onValueChange={changePassword}
            >
              <PasswordRules rules={rules} />
            </PasswordField>
            <PasswordField
              label='Type it again'
              value={confirmation}
              autoComplete='new-password'
              error={confirmationError}
              inputRef={confirmationRef}
              readOnly={isChanging}
              onValueChange={changeConfirmation}
            />
            <SubmitButton
              label='Change password'
              workingLabel='Changing password'
              isWorking={isChanging}
            />
          </form>
        </>
      )}
      {step === 'done' && (
        <>
          <CardHead
            mark={<StatusOrb tone='success' />}
            title='Password changed'
            autoFocusTitle
          >
            Your other devices are signed out. Sign in again with the new
            password.
          </CardHead>
          <div className='flex justify-end'>
            <Button variant='outline' size='lg' onClick={onSignIn}>
              Sign in
            </Button>
          </div>
        </>
      )}
    </StepSwap>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  CheckIcon,
  CircleIcon,
  EyeIcon,
  EyeOffIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Field, FieldDescription, FieldLabel } from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';

import { ErrorPresence } from './auth-kit';

export const PASSWORD_MIN_LENGTH = 10;

const PERSONAL_WORD_MIN_LENGTH = 3;

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const UPPERCASE_PATTERN = /\p{Lu}/u;

const LOWERCASE_PATTERN = /\p{Ll}/u;

const DIGIT_PATTERN = /\d/;

export type PasswordRule = {
  id: string;
  label: string;
  isMet: boolean;
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function isTellingWord(word: string) {
  return word.length >= PERSONAL_WORD_MIN_LENGTH;
}

/** Words that would make the password easy to guess: parts of the name and of the email. */
export function personalWordsOf(name: string, email: string) {
  const loweredName = name.toLowerCase();
  const loweredEmail = email.toLowerCase();
  const [localPart] = loweredEmail.split('@');
  const nameParts = loweredName.split(/\s+/);
  const words = [...nameParts, localPart];
  return words.filter(isTellingWord);
}

export function rulesOf(
  password: string,
  personalWords: string[]
): PasswordRule[] {
  const lowered = password.toLowerCase();
  const hasPassword = password.length > 0;
  const isLongEnough = password.length >= PASSWORD_MIN_LENGTH;
  const hasDigit = DIGIT_PATTERN.test(password);
  const hasUppercase = UPPERCASE_PATTERN.test(password);
  const hasLowercase = LOWERCASE_PATTERN.test(password);
  const hasBothCases = hasUppercase && hasLowercase;
  const usesPersonalWord = personalWords.some((word) => lowered.includes(word));
  const isImpersonal = hasPassword && !usesPersonalWord;
  return [
    {
      id: 'length',
      label: `At least ${PASSWORD_MIN_LENGTH} characters`,
      isMet: isLongEnough,
    },
    { id: 'digit', label: 'One number', isMet: hasDigit },
    {
      id: 'cases',
      label: 'Upper and lower case letters',
      isMet: hasBothCases,
    },
    {
      id: 'personal',
      label: 'Not your name or email',
      isMet: isImpersonal,
    },
  ];
}

export function areRulesMet(rules: PasswordRule[]) {
  return rules.every((rule) => rule.isMet);
}

function metCountLabelOf(rules: PasswordRule[]) {
  const metCount = rules.filter((rule) => rule.isMet).length;
  return `${metCount} of ${rules.length} password rules met`;
}

function RuleMark({ isMet }: { isMet: boolean }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const markKey = String(isMet);

  return (
    <span aria-hidden='true' className='relative flex size-4 shrink-0'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={markKey}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
          className='flex size-4 items-center justify-center'
        >
          {isMet && (
            <span className='bg-success/15 text-success-foreground flex size-4 items-center justify-center rounded-full'>
              <CheckIcon strokeWidth={2.5} className='size-2.5' />
            </span>
          )}
          {!isMet && (
            <CircleIcon className='text-muted-foreground/60 size-3.5' />
          )}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

/** Rules tick one by one as the password meets them. Rendered inside the password `Field`. */
export function PasswordRules({ rules }: { rules: PasswordRule[] }) {
  const metCountLabel = metCountLabelOf(rules);

  return (
    <FieldDescription render={<div />} className='pt-2.5'>
      <ul className='grid gap-x-4 gap-y-1.5 sm:grid-cols-2'>
        {rules.map((rule) => (
          <li
            key={rule.id}
            className={cn(
              'flex items-center gap-2 transition-colors duration-150',
              rule.isMet && 'text-foreground'
            )}
          >
            <RuleMark isMet={rule.isMet} />
            {rule.label}
          </li>
        ))}
      </ul>
      <span aria-live='polite' className='sr-only'>
        {metCountLabel}
      </span>
    </FieldDescription>
  );
}

function inputTypeOf(isRevealed: boolean) {
  if (isRevealed) {
    return 'text';
  }
  return 'password';
}

function revealLabelOf(isRevealed: boolean) {
  if (isRevealed) {
    return 'Hide password';
  }
  return 'Show password';
}

type PasswordFieldProps = {
  label: string;
  value: string;
  autoComplete: 'new-password' | 'current-password';
  error: string | null;
  autoFocus?: boolean;
  inputRef?: React.Ref<HTMLInputElement>;
  readOnly?: boolean;
  onValueChange: (value: string) => void;
  children?: React.ReactNode;
};

/** The reveal button swaps its eye; the value never leaves the field's state. */
export function PasswordField({
  label,
  value,
  autoComplete,
  error,
  autoFocus,
  inputRef,
  readOnly,
  onValueChange,
  children,
}: PasswordFieldProps) {
  const [isRevealed, setIsRevealed] = useState(false);
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const hasError = Boolean(error);
  const inputType = inputTypeOf(isRevealed);
  const revealLabel = revealLabelOf(isRevealed);
  const glyphKey = String(isRevealed);

  function changeValue(event: React.ChangeEvent<HTMLInputElement>) {
    onValueChange(event.target.value);
  }

  function toggleReveal() {
    setIsRevealed((current) => !current);
  }

  return (
    <Field invalid={hasError} className='gap-0'>
      <FieldLabel className='mb-1.5'>{label}</FieldLabel>
      <div className='relative'>
        <Input
          ref={inputRef}
          type={inputType}
          value={value}
          autoComplete={autoComplete}
          autoCapitalize='none'
          autoCorrect='off'
          spellCheck={false}
          autoFocus={autoFocus}
          readOnly={readOnly}
          onChange={changeValue}
          className='pr-10'
        />
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label={revealLabel}
          aria-pressed={isRevealed}
          onClick={toggleReveal}
          className='text-muted-foreground absolute top-1/2 right-0.5 -translate-y-1/2'
        >
          <AnimatePresence mode='popLayout' initial={false}>
            <motion.span
              key={glyphKey}
              variants={variants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
              className='flex'
            >
              {isRevealed && <EyeOffIcon />}
              {!isRevealed && <EyeIcon />}
            </motion.span>
          </AnimatePresence>
        </Button>
      </div>
      <ErrorPresence error={error} />
      {children}
    </Field>
  );
}

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function emailProblemOf(email: string, emptyMessage: string) {
  const trimmed = email.trim();
  if (trimmed.length === 0) {
    return emptyMessage;
  }
  const isValid = EMAIL_PATTERN.test(trimmed);
  if (!isValid) {
    return 'Enter an email like name@company.com';
  }
  return null;
}

